local function model(name)
    local value = cache[name]
    if value ~= nil then return value end
    local build = factories[name]
    if build == nil then return nil end
    value = build()
    cache[name] = value
    factories[name] = nil
    return value
end
function LightRpBoardGameModels.board(kind) return model(kind .. "_board") end
function LightRpBoardGameModels.piece(kind, side, gameKind)
    return model((gameKind or "chess") .. "_" .. side .. "_" .. kind)
end
